const boardEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const CHIP_COLORS=['象牙白','酒紅','寶藍','翠綠','紫'];
export function chipColorIndex(amount,bank){const values=getChipDenominations(bank);let index=0;for(let i=0;i<values.length;i++)if(amount>=values[i])index=i;return index;}
let chipClipSerial=0;
function chipSprite(index,x,y,size,art){const i=Math.max(0,Math.min(4,index)),clip='chip-crop-'+(++chipClipSerial);return `<svg x="${x}" y="${y}" width="${size}" height="${size}" viewBox="${i*434.4+20} 155 394.4 394" preserveAspectRatio="xMidYMid meet" overflow="hidden" aria-hidden="true"><defs><clipPath id="${clip}"><rect x="${i*434.4+20}" y="155" width="394.4" height="394"/></clipPath></defs><g clip-path="url(#${clip})"><image width="2172" height="724" href="${boardEscape(art('/art/sicbo-board-b/chips-five.png'))}"/></g></svg>`;}
export function chipFace(index,label,art){return `<span class="chip-face">${chipSprite(index,0,0,72,art)}<b>${boardEscape(label)}</b></span>`;}
export function baccaratBoardMarkup(enabled){
 return `<svg class="sicbo-tabletop baccarat-board" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 610" role="group" aria-label="百家樂主注及三款旁注盤面">${BACCARAT_CELLS.map(c=>`<g class="printed-cell" data-action="bet" data-bet="${c.id}" role="button" tabindex="${enabled?0:-1}" aria-disabled="${!enabled}" aria-label="${c.label}，${c.detail||'淨賠'+c.rate+'比1'}"><rect class="cell-bg" x="${c.x}" y="${c.y}" width="${c.w}" height="${c.h}" rx="12" fill="none" stroke="#c3a263" stroke-width="2"/><text x="${c.anchor.x}" y="${c.sideBet?407:115}" text-anchor="middle" fill="#f4e7c9" font-size="${c.sideBet?56:84}" font-weight="700">${c.label}</text><text x="${c.anchor.x}" y="${c.sideBet?562:300}" text-anchor="middle" fill="#d9c190" font-size="${c.sideBet?32:36}">${c.rateLabel||(c.id==='bac-banker'?'0.95:1':c.rate+':1')}</text></g>`).join('')}<g class="board-amounts" pointer-events="none"></g></svg>`;
}
export function boardMarkup(art,enabled){
  return BOARD_TEMPLATE.replace('__DICE__',()=>boardEscape(art('/art/sicbo-board-b/dice.png'))).replace('__FELT__',()=>boardEscape(art('/art/sicbo-board-b/felt.png'))).replaceAll('tabindex="0"',`tabindex="${enabled?0:-1}" aria-disabled="${!enabled}"`);
}
export function boardAmounts(bets,pending,art,counts={},lasts={},bank=10000,stacks={}){
  return ALL_BOARD_CELLS.map(c=>{
    const value=(bets[c.id]||0)-(pending[c.id]||0);if(value<=0)return '';
    const size=c.kind==='baccarat'?(c.chipSize||140):Math.min(78,c.w*.65,c.h*.8),x=c.anchor.x,y=c.anchor.y;
    const label=boardEscape(chipLabel(value)),font=c.kind==='baccarat'?36:14,height=c.kind==='baccarat'?50:23;const width=Math.min(c.w-6,Math.max(42,label.length*(font*.65)+16));
    const amounts=stacks[c.id]?.length?stacks[c.id]:Array(Math.min(3,counts[c.id]||1)).fill(lasts[c.id]||value);const top=amounts.at(-1);const index=chipColorIndex(top,bank);
    const underneath=amounts.slice(0,-1).map((amount,i,a)=>chipSprite(chipColorIndex(amount,bank),x-size/2-(a.length-i)*5,y-size/2+(a.length-i)*5,size,art)).join('');
    return `<g data-amount-bet="${c.id}">${underneath}<title>${boardEscape(ALL_BOARD_BETS[c.id].label)} 已押 ${money(value)}</title>${chipSprite(index,x-size/2,y-size/2,size,art)}<text x="${x}" y="${y+size*.035}" text-anchor="middle" fill="#19352b" font-size="${Math.max(9,size*.16)}" font-weight="700">${boardEscape(chipLabel(top))}</text><rect x="${x-width/2}" y="${y+size*.12}" width="${width}" height="${height}" rx="${height/2}" fill="#112c21" stroke="#e4c581"/><text x="${x}" y="${y+size*.12+height*.72}" text-anchor="middle" fill="#f7ddb0" font-size="${font}" font-weight="700">${label}</text></g>`;
  }).join('');
}
// Presentation only: accepted wagers belong to Game; flights never change money or saves.
export class ChipFlights {
  constructor({art,onChange,reduced=()=>false}){this.art=art;this.onChange=onChange;this.reduced=reduced;this.flights=[];}
  get pending(){const sums={};for(const f of this.flights)sums[f.id]=(sums[f.id]||0)+f.amount;return sums;}
  queue(id,amount,from,color=3){if(this.reduced())return;while(this.flights.length>=24)this.finish(this.flights[0]);this.flights.push({id,amount,from,color});}
  finish(f){const i=this.flights.indexOf(f);if(i<0)return;this.flights.splice(i,1);f.animation?.cancel();f.node?.remove();this.onChange();}
  cancel(id){for(const f of [...this.flights])if(!id||f.id===id)this.finish(f);}
  pause(paused){for(const f of this.flights)if(f.animation){if(paused)f.animation.pause();else f.animation.play();}}
  mount(){
    for(const f of [...this.flights]){
      if(f.node)continue;
      const cell=ALL_BOARD_CELLS.find(c=>c.id===f.id),svg=document.querySelector('.sicbo-tabletop'),matrix=svg?.getScreenCTM();
      if(!matrix){this.finish(f);continue;}
      const end=new DOMPoint(cell.anchor.x,cell.anchor.y).matrixTransform(matrix);
      const origin=f.from||{x:end.x,y:end.y+180};
      const n=document.createElement('div');n.className='flying-chip';n.setAttribute('aria-hidden','true');
      const baseSize=cell.kind==='baccarat'?(cell.chipSize||140):Math.min(78,cell.w*.65,cell.h*.8);const size=Math.max(20,baseSize*Math.abs(matrix.a));n.style.width=size+'px';n.style.height=size+'px';
      n.innerHTML=chipFace(f.color,chipLabel(f.amount),this.art);
      document.body.append(n);f.node=n;
      if(!n.animate){this.finish(f);continue;}
      const frames=[];
      for(let i=0;i<=20;i++){const t=i/20,e=1-Math.pow(1-t,3);frames.push({offset:t*.7,transform:`translate(${origin.x+(end.x-origin.x)*e-size/2}px,${origin.y+(end.y-origin.y)*e-Math.sin(Math.PI*t)*80-size/2}px) scale(${1+.12*Math.sin(Math.PI*t)})`});}
      frames.push({offset:.85,transform:`translate(${end.x-size/2}px,${end.y-size/2-4}px) scale(1.04)`},{offset:1,transform:`translate(${end.x-size/2}px,${end.y-size/2}px) scale(1)`});
      f.animation=n.animate(frames,{duration:600,easing:'linear',fill:'forwards'});f.animation.onfinish=()=>this.finish(f);
    }
  }
}
